const $=id=>document.getElementById(id);let current;
const rupees=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);
function render(trip){current=trip;$('trip-title').textContent=`${trip.days} days in ${trip.nickname}`;$('metrics').replaceChildren();for(const [value,label] of [[trip.days,'days of discovery'],[trip.travellers,'travellers'],[rupees(trip.estimate),'estimated group cost']]){const div=document.createElement('div');div.className='metric';const strong=document.createElement('strong');strong.textContent=value;const span=document.createElement('span');span.textContent=label;div.append(strong,span);$('metrics').append(div);}$('budget-message').textContent=(trip.withinBudget?`${rupees(trip.budget-trip.estimate)} below your budget.`:`About ${rupees(trip.estimate-trip.budget)} above your budget. Consider fewer days or a larger budget.`)+' Illustrative stay, meals and local transport only; excludes travel to destination, tickets and paid activities.';$('itinerary').replaceChildren();for(const day of trip.itinerary){const article=document.createElement('article');article.className='day';const num=document.createElement('div');num.className='day-number';num.textContent=String(day.day).padStart(2,'0');const content=document.createElement('div');const title=document.createElement('h3');title.textContent=day.title;content.append(title);for(const slot of ['morning','afternoon','evening']){const p=document.createElement('p');const b=document.createElement('b');b.textContent=slot[0].toUpperCase()+slot.slice(1)+' · ';p.append(b,document.createTextNode(day[slot]));content.append(p);}article.append(num,content);$('itinerary').append(article);}}
function generate(){try{render(TripPlanner.plan({destination:$('destination').value,days:Number($('days').value),travellers:Number($('travellers').value),budget:Number($('budget').value),style:$('style').value}));$('status').textContent='';}catch(error){$('status').textContent=error.message;}}
$('planner').addEventListener('submit',e=>{e.preventDefault();generate();});$('save').onclick=()=>{try{localStorage.setItem('trippilot:trip',JSON.stringify(current));$('status').textContent='Saved on this browser.';}catch{$('status').textContent='Browser storage is unavailable. You can download the trip instead.';}};$('saved').onclick=()=>{try{const value=localStorage.getItem('trippilot:trip');if(!value){$('status').textContent='No saved trip yet. Plan one and select Save this trip.';return;}const trip=TripPlanner.plan(JSON.parse(value));for(const key of ['destination','days','travellers','budget','style'])$(key).value=trip[key];render(trip);$('status').textContent='Saved trip restored.';}catch{$('status').textContent='Could not restore the saved trip.';}};$('download').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(current,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='trippilot-itinerary.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};generate();
